import {topics,vocabulary,vocabQuestions,reading,listening,writing,speaking,questions} from './content.mjs';
import {pronunciations,officialAudio,officialHandbook,officialDigitalTest} from './pronunciations.mjs';
import {selectPractice,readState,saveState,todayKey,recordAnswer,recordActivity,wordCount,selectDaily,filterVocabulary} from './state.mjs';
const main=document.querySelector('#main');
const state=readState();
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={vocabulary:'單字',reading:'閱讀',listening:'聽力',writing:'寫作',speaking:'口說'};
let quiz=null,topic='全部',vocabQuery='',cardIndex=0,wordPage=0,flipped=false,homeFlipped=false,noticeTimer,storageWarned=false,speechToken=0;
const WORDS_PER_PAGE=24;
const icons={book:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z"/><path d="M12 6v15"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>',pen:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14z"/><path d="M13 20h8"/>',chat:'<path d="M20 11a8 8 0 0 1-8 8H5l-4 3 2-7a8 8 0 1 1 17-4z"/><path d="M6 10h10M6 14h6"/>',check:'<rect x="4" y="3" width="16" height="19" rx="3"/><path d="m8 12 3 3 5-6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',leaf:'<path d="M19 3C4 2 1 12 7 17c7 5 14-2 12-14Z"/><path d="M4 22 15 8"/>'};
const icon=n=>n==='letters'?'<span aria-hidden="true">Aa</span>':`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.check}</svg>`;
const modules=[['vocabulary','單字花園','Vocabulary','把生活裡的單字，變成自己的。','letters','mint',`${vocabulary.length} 個單字 · ${topics.length} 個主題`],['reading','閱讀小徑','Reading','讀懂短訊息，找到關鍵線索。','book','yellow',`${reading.length} 題 · 短文與選字`],['listening','聽力時光','Listening','放慢一點，聽懂每一個重點。','headphones','blue',`${listening.length} 題 · 日常對話`],['writing','寫作練習','Writing','從一句話開始，把想法寫下來。','pen','peach',`${writing.length} 個任務 · 引導寫作`],['speaking','開口說說','Speaking','用英文，分享自己的小世界。','chat','lavender',`${speaking.length} 個話題 · 親子陪練`],['mistakes','錯題筆記','Review','再試一次，就比昨天更熟練。','check','rose','專屬於你的複習清單']];
function notify(message){const el=document.querySelector('#notice');el.textContent=message;el.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.hidden=true,5000)}
function persist(){const ok=saveState(state);if(!ok&&!storageWarned){notify('瀏覽器目前無法儲存進度。你仍可繼續練習，關閉頁面前請另存作文。');storageWarned=true}return ok}
function updateBadge(){document.querySelector('#mistake-count').textContent=state.mistakes.filter(id=>questions.some(q=>q.id===id)).length}
function stats(){const date=todayKey(),events=[...state.answers,...state.activities];return{today:state.answers.filter(a=>a.date===date).length,days:new Set(events.map(a=>a.date)).size,correct:state.answers.filter(a=>a.correct).length,total:state.answers.length,mistakes:state.mistakes.length}}
function summaryStats(){const s=stats();return `<div class="stats"><div class="stat"><span class="stat-icon">${icon('check')}</span><div><strong>${s.today}<small>題</small></strong><p>今天完成的選擇題</p></div></div><div class="stat"><span class="stat-icon">${icon('sun')}</span><div><strong>${s.days}<small>天</small></strong><p>累積學習日</p></div></div><div class="stat"><span class="stat-icon">${icon('leaf')}</span><div><strong>${s.mistakes}<small>題</small></strong><p>等待複習的錯題</p></div></div></div>`}
function courseGrid(){return `<div class="courses">${modules.map(([id,title,en,desc,i,color,count])=>`<a class="course" href="#${id}"><div class="course-top"><span class="icon ${color}">${icon(i)}</span><span class="course-tag">${id==='mistakes'?'MY REVIEW':'A2 KEY'}</span></div><h3>${title}<span>${en}</span></h3><p>${desc}</p><div class="course-foot"><span>${id==='mistakes'?`${stats().mistakes} 題等待複習`:count}</span><b aria-hidden="true">↗</b></div></a>`).join('')}</div>`}
function heading(title,desc,en='YOUR LEARNING SPACE'){return `<a class="back" href="#practice">← 返回複習主題</a><div class="page-heading"><div class="eyebrow">${en}</div><h1>${title}</h1><p>${desc}</p></div>`}
function pronunciationPage(word){return `https://dictionary.cambridge.org/pronunciation/english/${encodeURIComponent(word.toLowerCase().replace(/\s+/g,'-'))}`}
function home(){const date=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'});const recorded=vocabulary.filter(v=>pronunciations[v.word]);const v=selectDaily(recorded,todayKey(),1)[0];const p=pronunciations[v.word];return `<div class="welcome"><p>HELLO, LITTLE LEARNER <span aria-hidden="true">☀</span></p><span class="date-label">${date}</span></div><div class="hero-grid"><section class="hero"><span class="hero-tag">one more try, one step closer</span><div class="eyebrow"><span aria-hidden="true">✦</span> YOUR EXAM PRACTICE SPACE</div><h1>準備好了嗎？<br>一起<em>練出</em>信心。</h1><p>照自己的步調練習。再做一組，離目標更近一點。</p><div class="hero-bottom"><a class="btn" href="#sprint">開始連續練習 <span aria-hidden="true">↗</span></a><span class="subtle">不限次數 · 新題優先<br>做完一組，隨時接著練</span></div></section><section class="word-card" aria-label="每日單字"><div class="eyebrow">WORD OF THE DAY · 每日單字</div><button class="word-flip" data-action="home-flip" aria-label="${homeFlipped?'顯示英文單字':'翻開中文意思'}"><span class="word" lang="en">${homeFlipped?esc(v.zh):esc(v.word)}</span><span class="phonetic">${homeFlipped?esc(v.word):`UK /${p.ipa}/`}</span></button><div class="word-divider"></div><p>${homeFlipped?esc(v.translation):'認識一個新單字，開啟新的一天。'}</p><div><a class="text-button" href="${p.source}" target="_blank" rel="noopener noreferrer">到 Cambridge 聽英式發音 ↗</a><button class="text-button" data-action="home-flip">${homeFlipped?'翻回英文':'翻開意思'} ↗</button></div><small class="subtle">會開啟 Cambridge Dictionary 官方發音頁<br>請在 UK 區塊按播放鍵</small></section></div>${summaryStats()}<div class="section-head"><div><h2>今天，想練習什麼？</h2><p>選一個主題，讓每一步都算數。</p></div><a href="#progress">看看我的進步 ↗</a></div>${courseGrid()}<aside class="tip"><span class="tip-icon" aria-hidden="true">✦</span><div><strong>給今天的你：答錯，也是學會的開始。</strong><p>讀一讀解析，再回到錯題筆記試一次。不用趕，我們一起慢慢來。</p></div></aside>`}
function practice(){return `<div class="sprint-banner"><div><strong>考前連續練習</strong><p>選主題、選題數，不限次數。未練過的題目優先出現。</p></div><a class="btn" href="#sprint">開始衝刺 ↗</a></div><div class="page-heading"><div class="eyebrow">A LITTLE PRACTICE, EVERY DAY</div><h1>找到今天的小目標。</h1><p>先練單字、讀一段短文，或和家人用英文聊聊天。</p></div>${courseGrid()}<aside class="tip"><div><strong>這裡怎麼對應 KET？</strong><p>A2 Key for Schools 包含閱讀與寫作、聽力及口說。本網站提供分項暖身與原創小練習，並非完整模擬考。<a class="inline-link" href="https://www.cambridgeenglish.org/exams-and-tests/qualifications/key/format/" target="_blank" rel="noopener noreferrer">查看官方考試形式 ↗</a></p></div></aside>`}
function cards(){
 const pool=filterVocabulary(vocabulary,{query:vocabQuery,topic});
 const search=`<form id="vocab-search-form" class="vocab-search" role="search"><label for="vocab-search">搜尋英文或中文</label><div><input id="vocab-search" name="query" type="search" value="${esc(vocabQuery)}" placeholder="例如：library、圖書館"><button class="btn" type="submit">搜尋</button>${vocabQuery?'<button class="btn secondary" type="button" data-action="clear-vocab-search">清除</button>':''}</div></form><p class="vocab-results" role="status" aria-live="polite">找到 ${pool.length} 個單字${topic==='全部'?'':` · ${esc(topic)}`}</p>`;
 const chips=`<div class="chips" aria-label="單字主題">${['全部',...topics].map(t=>`<button class="chip ${t===topic?'active':''}" data-action="topic" data-topic="${t}" aria-pressed="${t===topic}">${t}</button>`).join('')}</div>`;
 if(!pool.length)return `${heading('單字花園','從 15 個生活主題中搜尋、翻卡和練習。','GROW YOUR WORDS')}${search}${chips}<section class="panel empty"><span class="icon mint">${icon('letters')}</span><h2>找不到符合的單字</h2><p>試試較短的英文、中文關鍵字，或切換到「全部」主題。</p><button class="btn" data-action="clear-vocab-search">清除搜尋</button></section>`;
 const pageCount=Math.ceil(pool.length/WORDS_PER_PAGE);wordPage=Math.max(0,Math.min(wordPage,pageCount-1));
 const pageStart=wordPage*WORDS_PER_PAGE,pageWords=pool.slice(pageStart,pageStart+WORDS_PER_PAGE);
 cardIndex=Math.max(0,Math.min(cardIndex,pool.length-1));if(cardIndex<pageStart||cardIndex>=pageStart+WORDS_PER_PAGE)cardIndex=pageStart;
 const v=pool[cardIndex],p=pronunciations[v.word],source=p?.source||pronunciationPage(v.word);
 const reverse=flipped?(v.example?`<span class="translation">${esc(v.zh)}</span><span class="example" lang="en">${esc(v.example)}</span><small>${esc(v.translation)}</small>`:`<span class="translation">${esc(v.zh)}</span><span class="example">A2 Key 核心字彙</span><small>主題：${esc(v.topic)}</small>`):`<span class="phonetic">${esc(v.pos)}${p?` · UK /${esc(p.ipa)}/`:' · 英式發音'}</span><span class="word" lang="en">${esc(v.word)}</span><small>先想一想，再點一下翻卡 ↻</small>`;
 return `${heading('單字花園','從 15 個生活主題中搜尋、翻卡和練習。','GROW YOUR WORDS')}${search}${chips}<div class="learning-layout"><section class="panel"><div class="question-meta"><span>${esc(v.topic)}</span><span>${cardIndex+1} / ${pool.length}</span></div><button class="flashcard" data-action="flip" aria-label="${flipped?'翻回英文單字':'翻開中文意思'}">${reverse}</button><div class="flash-controls"><button class="btn secondary" data-action="prev-card" ${cardIndex===0?'disabled':''}>← 上一張</button><a class="text-button" href="${source}" target="_blank" rel="noopener noreferrer">到 Cambridge 聽英式發音 ↗</a><button class="btn secondary" data-action="next-card" ${cardIndex===pool.length-1?'disabled':''}>下一張 →</button></div><div class="audio-source"><span>官方網站播放 · 請在 UK 區塊按播放鍵</span>${v.example?`<button class="text-button" data-action="say-example" data-id="${v.id}">聽例句（裝置合成語音）</button>`:''}</div><div class="word-grid">${pageWords.map((w,i)=>`<button class="word-item ${pageStart+i===cardIndex?'current':''}" data-action="pick-card" data-index="${pageStart+i}" aria-label="查看 ${esc(w.word)}" ${pageStart+i===cardIndex?'aria-current="true"':''}><span lang="en">${esc(w.word)}</span><small>${esc(w.zh)}</small></button>`).join('')}</div><div class="word-pagination"><button class="btn secondary" data-action="prev-word-page" ${wordPage===0?'disabled':''}>← 上一頁</button><span>第 ${wordPage+1} / ${pageCount} 頁</span><button class="btn secondary" data-action="next-word-page" ${wordPage===pageCount-1?'disabled':''}>下一頁 →</button></div></section><aside class="aside-panel"><h3>把單字放進生活裡</h3><p>先看英文、自己想意思，再翻卡確認並跟著發音唸一次。</p><ul><li>可用英文或中文搜尋。</li><li>15 個主題可分開練習。</li><li>做完一組小測驗，可立刻再練。</li></ul><button class="btn" data-action="vocab-quiz">開始單字小測驗 ↗</button><p class="small-note">測驗範圍：${esc(topic)}<br>每回合最多 6 題，不限重練次數。<br>所有單字都可直接前往 Cambridge Dictionary 官方發音頁；36 個常用詞另在卡片顯示 UK 音標。</p></aside></div>`
}
function lessonPicker(category){const isReading=category==='reading',pool=isReading?reading:listening;const blocks=[];for(let i=0;i<pool.length;i+=isReading?6:5)blocks.push(pool.slice(i,i+(isReading?6:5)));return `${heading(isReading?'閱讀小徑':'聽力時光',isReading?'慢慢讀，找出時間、地點和真正要傳達的訊息。':'可以重播，也可以調慢速度。送出答案後，就能查看逐字稿。',isReading?'READ & DISCOVER':'LISTEN & NOTICE')}${!isReading?'<div class="sprint-banner official-banner"><div><strong>想熟悉真正考試的聲音？</strong><p>直接聽 Cambridge 官方樣題錄音，搭配官方試題作答。</p></div><a class="btn" href="#official">官方聽力樣題 ↗</a></div>':''}<div class="learning-layout"><section class="list">${blocks.map((group,i)=>`<article class="task-card"><span class="icon ${isReading?'yellow':'blue'}">${icon(isReading?'book':'headphones')}</span><div><h3>${isReading?['生活裡的小訊息','短文與文法線索'][i]:['日常對話練習','聽懂安排與變化'][i]}</h3><p>${group.length} 題 · ${isReading?'約 5–8 分鐘':'約 6–10 分鐘'}</p></div><button class="btn secondary" data-action="start-block" data-category="${category}" data-block="${i}">開始練習 ↗</button></article>`).join('')}</section><aside class="aside-panel"><h3>${isReading?'閱讀小提醒':'聽力小提醒'}</h3><p>${isReading?'先看問題，再讀文章。遇到不認識的單字，先用上下文推測意思，不必每個字都查。':'先看問題，想想要找的是時間、價格還是地點。聽到 but、instead 時，留意資訊是否改變。'}</p>${!isReading?'<p class="small-note">本區使用瀏覽器英文合成語音，非真人錄音；裝置的聲音可能不同，不代表正式考試音訊。</p>':''}</aside></div>`}
function startQuiz(pool,title,kind='quiz'){quiz={pool:[...pool],title,kind,index:0,selected:null,submitted:false,correct:0,results:[],attempt:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`};if(location.hash==='#quiz'){render();}else location.hash='quiz';}
function startDaily(){const date=todayKey();const pool=[...selectDaily(vocabQuestions,date,3),...selectDaily(reading,date,3),...selectDaily(listening,date,2)];quiz={pool,title:'今日小挑戰',kind:'daily',index:0,selected:null,submitted:false,correct:0,results:[],attempt:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`};}
function questionView(){if(!quiz?.pool.length)return empty('先挑一個練習吧','選擇單字、閱讀或聽力，就能開始新的小挑戰。','#practice','選擇練習');if(quiz.index>=quiz.pool.length)return resultView();const q=quiz.pool[quiz.index],done=quiz.submitted,correct=quiz.selected===q.answer;return `${heading(quiz.title,`第 ${quiz.index+1} 題，共 ${quiz.pool.length} 題。做完這一題，再往前一步。`,'ONE QUESTION AT A TIME')}<div class="learning-layout"><section class="panel"><div class="question-meta"><span class="tag">${labels[q.category]} · ${q.topic}</span><span>${quiz.index+1} / ${quiz.pool.length}</span></div><div class="progress" role="progressbar" aria-label="本回合進度" aria-valuenow="${quiz.index+(done?1:0)}" aria-valuemin="0" aria-valuemax="${quiz.pool.length}"><span style="width:${(quiz.index+(done?1:0))/quiz.pool.length*100}%"></span></div>${q.category==='listening'?`<div class="audio-box"><div class="audio-label">LISTEN CAREFULLY · 聽聽看</div><div class="audio-controls"><button class="btn" data-action="play-question">▶ 播放對話</button><button class="text-button" data-action="stop-audio">停止</button><label><span class="sr-only">語音播放速度</span><select id="speech-rate"><option value="0.9">一般速度</option><option value="0.7">慢速練習</option></select></label></div><p id="speech-status" role="status" class="speech-status">瀏覽器英文合成語音 · 可以重複播放</p></div>`:`<div class="passage" lang="en">${esc(q.passage)}</div>`}<form id="answer-form"><h2 id="question-title" class="question" lang="en">${esc(q.question)}</h2><fieldset class="choices" ${done?'disabled':''}><legend class="sr-only">選擇一個答案</legend>${q.choices.map((c,i)=>`<label class="choice ${done?(i===q.answer?'correct':i===quiz.selected?'incorrect':''):''}"><input type="radio" name="answer" value="${i}" ${quiz.selected===i?'checked':''} required><span class="choice-letter" aria-hidden="true">${'ABC'[i]}</span><span lang="${q.category==='vocabulary'?'zh-Hant':'en'}">${esc(c)}</span>${done&&i===q.answer?'<span class="choice-result">✓ 正確答案</span>':done&&i===quiz.selected?'<span class="choice-result">再想想</span>':''}</label>`).join('')}</fieldset>${done?`<div class="feedback ${correct?'':'wrong'}" id="feedback" role="status" tabindex="-1"><h3>${correct?'答對了！你找到線索了。':'差一點，再看看這個線索。'}</h3><p>${esc(q.explanation)}</p>${!correct?'<p class="subtle">已放進錯題筆記，下次可以再試一次。</p>':''}</div>${q.script?`<details><summary>查看英文逐字稿</summary><p lang="en">${esc(q.script)}</p></details>`:''}`:''}<div class="actions">${done?`<span class="subtle">先讀完解析，再繼續。</span><button class="btn" type="button" data-action="next-question">${quiz.index===quiz.pool.length-1?'看看練習成果':'下一題'} →</button>`:'<span class="subtle">選好後，就可以確認答案。</span><button class="btn" type="submit">確認答案 →</button>'}</div></form></section><aside class="aside-panel"><h3>不急，找到自己的步調。</h3><p>${q.category==='listening'?'可以先看問題再播放。注意對話最後確認的安排，不要只記住第一個聽到的數字。':q.category==='reading'?'注意問題中的關鍵字，再回到原文尋找支持答案的句子。':'先看例句，想一想這個單字在句子裡代表什麼。'}</p><p class="small-note">答題後立即保存進度。離開或重新整理會結束目前回合；已完成的題目與錯題仍會保留。</p></aside></div>`}
function submitAnswer(form){if(!quiz||quiz.submitted)return;const chosen=new FormData(form).get('answer');if(chosen===null){notify('先選擇一個答案，再按確認。');return}const index=Number(chosen),q=quiz.pool[quiz.index];if(!Number.isInteger(index)||index<0||index>=q.choices.length)return;stopSpeech();quiz.selected=index;quiz.submitted=true;const correct=index===q.answer;if(correct)quiz.correct++;quiz.results.push({id:q.id,correct});recordAnswer(state,{attempt:quiz.attempt,id:q.id,category:q.category,correct,date:todayKey()});persist();render(false);document.querySelector('#feedback')?.focus();}
function resultView(){return `<section class="panel empty"><span class="icon mint">${icon('leaf')}</span><div class="eyebrow" style="margin-top:25px">A LITTLE PROGRESS, WELL DONE</div><h1>今天，又往前了一小步。</h1><div class="result-score">${quiz.correct}<small> / ${quiz.pool.length}</small></div><p>這回合答對 ${quiz.correct} 題。${quiz.correct===quiz.pool.length?'每一道線索，都被你找到了！':'讀過解析、願意再試一次，就是進步。'}<br><span class="subtle">這是本回合練習結果，不是官方考試分數。</span></p><div class="actions" style="justify-content:center"><a class="btn secondary" href="#home">回到我的花園</a><a class="btn secondary" href="#mistakes" style="margin-left:0">看看錯題筆記</a><button class="btn" data-action="continue-practice" style="margin-left:0">${quiz.kind==='sprint'?'繼續下一組':'再練一組'} →</button></div></section>`}
function empty(title,desc,href='#practice',button='挑一個練習'){return `<section class="panel empty"><span class="icon mint">${icon('check')}</span><h2>${title}</h2><p>${desc}</p><a class="btn" href="${href}">${button} ↗</a></section>`}
function mistakes(){const list=state.mistakes.map(id=>questions.find(q=>q.id===id)).filter(Boolean);return `${heading('錯題筆記','每一題答錯的地方，都藏著下一次進步的線索。','TRY AGAIN, GROW AGAIN')}${!list.length?empty('目前沒有待複習的錯題','開始一小組練習吧。答錯的題目會自動收在這裡。'):`<div class="section-head"><p class="subtle">共 ${list.length} 題 · 重答正確後，自動移出這裡</p><button class="btn" data-action="review-all">全部再練一次 ↗</button></div><div class="list">${list.map(q=>`<article class="task-card"><span class="icon ${q.category==='listening'?'blue':q.category==='reading'?'yellow':'mint'}">${icon(q.category==='listening'?'headphones':q.category==='reading'?'book':'letters')}</span><div><p>${labels[q.category]} · ${q.topic}</p><h3 lang="en">${esc(q.question)}</h3></div><button class="btn secondary" data-action="review-one" data-id="${q.id}">再試一次</button></article>`).join('')}</div>`}`}
function writingList(){return `${heading('寫作練習','用自己的話，把訊息說清楚。先試著寫，再對照參考答案。','MAKE YOUR WORDS COUNT')}<div class="list">${writing.map(w=>`<article class="task-card"><span class="icon peach">${icon('pen')}</span><div><h3>${w.title}</h3><p>${w.type} · 至少 ${w.min} 個英文單字${state.drafts[w.id]?' · 已有草稿':''}</p></div><a class="btn secondary" href="#writing/${w.id}">${state.drafts[w.id]?'繼續寫':'開始寫'} ↗</a></article>`).join('')}</div><aside class="tip"><div><strong>先寫出自己的版本，再比較</strong><p>短訊息練習至少 25 字，故事暖身至少 35 字。本網站提供字數與自我檢查，不會自動批改文法或給官方分數。故事暖身採文字情境，並非正式看圖寫作。</p></div></aside>`}
function writingView(id){const w=writing.find(w=>w.id===id);if(!w)return empty('找不到這個寫作任務','回到寫作頁，重新選擇一個題目。','#writing','查看寫作任務');const draft=state.drafts[id]||'';return `${heading(w.title,`${w.type} · 至少 ${w.min} 個英文單字。先把三個重點寫完整。`,'YOUR IDEAS, IN ENGLISH')}<div class="learning-layout"><section class="panel"><div class="writing-prompt" lang="en"><p>${esc(w.prompt)}</p><ul>${w.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul></div><label class="text-label" for="writing-draft">我的英文草稿</label><textarea id="writing-draft" data-id="${id}" lang="en" spellcheck="true" placeholder="Write your ideas here…">${esc(draft)}</textarea><div class="draft-meta"><span id="word-count">${wordCount(draft)} / ${w.min} 字（至少）</span><span id="draft-status" role="status">${draft?'已載入本機草稿':'輸入後自動儲存在目前瀏覽器'}</span></div><details><summary>寫完了？看看參考答案</summary><p class="sample" lang="en">${esc(w.sample)}</p><p>答案不只一種。先比較是否寫齊三個重點，再檢查句子。</p></details><div class="actions"><a class="btn secondary" href="#writing">其他寫作任務</a><button class="btn" data-action="finish-writing" data-id="${id}">完成自我檢查 ✓</button></div><p id="writing-feedback" class="small-note" role="status"></p></section><aside class="aside-panel"><h3>寫作小清單</h3><p>${w.tip}</p><div class="checklist">${w.hints.map((hint,i)=>`<label><input type="checkbox" name="writing-check" value="${i}"><span>${hint}</span></label>`).join('')}<label><input type="checkbox" name="writing-check" value="3"><span>我檢查過大小寫、句點和拼字。</span></label></div><p class="small-note">這份清單協助你自己檢查，並不是自動批改。也可以請家人或老師一起讀。</p></aside></div>`}
function speakingList(){return `${heading('開口說說','先自己回答，再看看示範。可以請家人用追問句，陪你多聊一點。','LET’S TALK ABOUT YOUR WORLD')}<div class="list">${speaking.map(s=>`<article class="task-card"><span class="icon lavender">${icon('chat')}</span><div><h3>${s.title}</h3><p>${s.topic} · 約 2–3 分鐘</p></div><a class="btn secondary" href="#speaking/${s.id}">開始說說 ↗</a></article>`).join('')}</div><aside class="tip"><div><strong>練習表達，不追求背出一模一樣的答案</strong><p>本站不錄音，也不自動評分。偏好討論採文字提示，供親子練習；正式口說考試的完整形式請參考 Cambridge 官方資料。</p></div></aside>`}
function speakingView(id){const s=speaking.find(s=>s.id===id);if(!s)return empty('找不到這個口說話題','回到口說頁，重新選擇一個話題。','#speaking','查看口說話題');return `${heading(s.title,'讀一讀問題，試著用兩到三句英文回答。','YOUR VOICE MATTERS')}<div class="learning-layout"><section class="panel"><div class="question-meta"><span class="tag">${s.topic}</span><span>親子陪練</span></div><div class="speaking-q" lang="en">${s.question}<p lang="zh-Hant">${s.zh}</p></div><button class="text-button" data-action="say-prompt" data-id="${id}">◖ 聽聽問題怎麼唸</button><h3 style="margin-top:24px">再多聊一句</h3><p lang="en" style="margin-top:12px">${s.follow}</p><details><summary>需要一點靈感？查看示範回答</summary><p class="sample" lang="en">${s.sample}</p><button class="text-button" data-action="say-sample" data-id="${id}">◖ 聽示範回答</button><p>把示範中的科目、活動或人物換成你自己的。播放使用瀏覽器合成語音。</p></details><div class="actions"><a class="btn secondary" href="#speaking">其他口說話題</a><button class="btn" data-action="finish-speaking" data-id="${id}">我練習過了 ✓</button></div><p id="speaking-feedback" role="status" class="small-note"></p></section><aside class="aside-panel"><h3>可以這樣開頭</h3>${s.stems.map(stem=>`<p lang="en" class="sentence-stem">${stem}</p>`).join('')}<p class="small-note">給陪練的家人：先聽孩子說完，再問一個簡短問題。願意表達，比說得完美更重要。</p></aside></div>`}
function progressView(){const s=stats(),events=[...state.answers,...state.activities];const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:todayKey(d),label:d.toLocaleDateString('zh-TW',{weekday:'narrow'}),day:d.getDate()}});return `${heading('我的進步','記錄真實練習的每一步，不需要和任何人比較。','LOOK HOW FAR YOU’VE GROWN')}${summaryStats()}<div class="progress-grid"><section class="panel"><h3>最近 7 天</h3><p class="small-note">完成選擇題、寫作自我檢查或口說練習，就會留下足跡。</p><div class="week">${week.map(d=>`<div class="day ${events.some(e=>e.date===d.key)?'done':''}"><span>${d.label}</span><b aria-label="${d.key} ${events.some(e=>e.date===d.key)?'已練習':'尚未練習'}">${events.some(e=>e.date===d.key)?'✓':d.day}</b></div>`).join('')}</div><div class="review-row"><span>累積選擇題作答次數</span><strong>${s.total} 次</strong></div><div class="review-row"><span>累積答對次數</span><strong>${s.correct} 次${s.total?` · ${Math.round(s.correct/s.total*100)}%`:''}</strong></div><p class="small-note">重複練習會計入作答次數；正確率不是官方考試分數。</p></section><section class="panel"><h3>各主題探索進度</h3>${[['vocabulary',vocabQuestions],['reading',reading],['listening',listening],['writing',writing],['speaking',speaking]].map(([id,pool])=>{const done=new Set((['writing','speaking'].includes(id)?state.activities:state.answers).filter(a=>a.category===id&&pool.some(q=>q.id===a.id)).map(a=>a.id)).size;return `<div class="progress-row"><div><span>${labels[id]}</span><span>${done} / ${pool.length}</span></div><div class="progress" role="progressbar" aria-label="${labels[id]}已練習數" aria-valuenow="${done}" aria-valuemin="0" aria-valuemax="${pool.length}"><span style="width:${done/pool.length*100}%"></span></div></div>`}).join('')}<p class="small-note">進度表示曾練習的不同題目或任務數，不代表熟練程度。</p></section></div>`}
function stopSpeech(){speechToken++;if('speechSynthesis' in window)speechSynthesis.cancel();document.querySelectorAll('audio').forEach(a=>a.pause());}
function speak(text,rate=.9){
 if(!('speechSynthesis' in window)){notify('這個瀏覽器不支援語音播放。請改用支援英文語音的瀏覽器，或作答後閱讀逐字稿。');return}
 stopSpeech();const token=speechToken;const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=rate;
 const voices=speechSynthesis.getVoices();const british=voices.filter(v=>v.lang.replace('_','-').toLowerCase()==='en-gb');u.voice=british.find(v=>/natural|premium|enhanced/i.test(v.name))||british[0]||null;if(voices.length&&!u.voice){notify('這台裝置沒有英式英文語音，可能使用系統預設聲音。單字請聽 Cambridge 錄音，聽力請用官方樣題。')}
 const status=document.querySelector('#speech-status');if(status)status.textContent='正在準備英文語音…';
 u.onstart=()=>{if(token===speechToken&&status?.isConnected)status.textContent='正在播放 · 可以隨時停止或重播'};
 u.onend=()=>{if(token===speechToken&&status?.isConnected)status.textContent='播放完畢 · 想再聽一次也可以'};
 u.onerror=e=>{if(token!==speechToken||['canceled','interrupted'].includes(e.error))return;if(status?.isConnected)status.textContent='無法播放語音，請檢查裝置的英文語音設定。';notify('英文語音無法播放，請檢查裝置語音設定，或改用其他瀏覽器。')};
 speechSynthesis.speak(u);
}

function sprintView(){const remaining=questions.filter(q=>!state.answers.some(a=>a.id===q.id)).length;return `${heading('考前連續練習','想練多久，由你決定。完成一組後可以直接開始下一組，不必等到明天。','PRACTISE AT YOUR OWN PACE')}<div class="learning-layout"><section class="panel"><h2>這一回合，想練什麼？</h2><label class="text-label" for="sprint-category">練習範圍</label><select class="wide-select" id="sprint-category"><option value="mixed">綜合練習（單字＋閱讀＋聽力）</option><option value="vocabulary">單字小測驗</option><option value="reading">閱讀與選字</option><option value="listening">原創聽力（合成語音）</option></select><label class="text-label" for="sprint-count">每組題數</label><select class="wide-select" id="sprint-count"><option value="5">5 題 · 短練習</option><option value="10" selected>10 題 · 集中練習</option><option value="20">20 題 · 多練一點</option><option value="all">此範圍全部題目</option></select><p class="small-note">優先選擇尚未作答、或練得較少的題目。若主題題數較少，會使用該主題全部題目，不會在同一回合重複出題。</p><div class="actions"><button class="btn" data-action="start-sprint">開始這一組 →</button></div></section><aside class="aside-panel"><h3>不限次數，持續練習</h3><p>原創選擇題共 ${questions.length} 題，目前還有 ${remaining} 題未練過。全部練過後會重新輪替，並不是無限新題庫。</p><ul><li>每題立即看中文解析。</li><li>答錯自動放進錯題筆記。</li><li>做完可繼續下一組。</li></ul><a class="btn secondary" href="#official">聽官方考試樣題 ↗</a></aside></div>`}
function runSprint(category,countChoice){const pool=category==='mixed'?questions:questions.filter(q=>q.category===category);const count=countChoice==='all'?pool.length:Number(countChoice);if(!pool.length||(![5,6,8,10,20].includes(count)&&countChoice!=='all'))return;const next=selectPractice(pool,state.answers,count,`${Date.now()}-${state.answers.length}`);startQuiz(next,category==='mixed'?'綜合連續練習':`${labels[category]}連續練習`,'sprint');quiz.sprintCategory=category;quiz.sprintCount=countChoice;}
function officialView(){return `${heading('Cambridge 官方聽力樣題','熟悉真正考試的聲音、語速與作答安排。這裡播放的是 Cambridge 官方公開錄音。','LISTEN TO THE REAL EXAM FORMAT')}<div class="learning-layout"><section class="panel"><span class="course-tag">CAMBRIDGE ENGLISH · 官方公開資源</span><h2 style="margin-top:20px">A2 Key for Schools</h2><p class="small-note">Handbook for teachers · Listening audio</p><audio id="official-audio" controls preload="none" src="${officialAudio}" aria-label="Cambridge A2 Key for Schools 官方聽力樣題錄音"></audio><p id="official-audio-status" role="status" class="small-note">按播放開始。建議先開啟下面的官方手冊，找到 Listening 的樣題，再搭配錄音作答。</p><div class="actions"><a class="btn" href="${officialHandbook}" target="_blank" rel="noopener noreferrer">開啟官方手冊與樣題 ↗</a><a class="btn secondary" href="${officialDigitalTest}" target="_blank" rel="noopener noreferrer">官方數位聽力模擬 ↗</a></div><p class="small-note">錄音與試題 © Cambridge University Press & Assessment，由官方網站提供。本頁不複製試題，也不把官方錄音混入原創題目。若播放器無法載入，可直接<a class="inline-link" href="${officialAudio}" target="_blank" rel="noopener noreferrer">開啟官方錄音</a>。</p></section><aside class="aside-panel"><h3>考前怎麼練？</h3><ol><li>先讀題目，圈出要找的資訊。</li><li>照錄音安排聽兩次，完成作答。</li><li>核對答案，再讀逐字稿。</li></ol><p>考試可能包含不同英語口音；練英式發音的同時，也要習慣官方錄音裡的不同聲音。</p><a class="inline-link" href="https://www.cambridgeenglish.org/exams-and-tests/qualifications/key/preparation/" target="_blank" rel="noopener noreferrer">查看 Cambridge 官方備考頁 ↗</a></aside></div>`}

function render(focus=true){const [page='home',id]=location.hash.slice(1).split('/');const route=page||'home';updateBadge();document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===(route==='home'||route==='progress'?'home':route==='mistakes'?'mistakes':'practice');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const renderers={home,practice,sprint:sprintView,official:officialView,vocabulary:cards,reading:()=>lessonPicker('reading'),listening:()=>lessonPicker('listening'),writing:()=>id?writingView(id):writingList(),speaking:()=>id?speakingView(id):speakingList(),mistakes,progress:progressView,quiz:questionView,daily:()=>{if(!quiz||quiz.kind!=='daily')startDaily();return questionView()}};
 main.innerHTML=(renderers[route]||(()=>empty('這條小徑還不存在','回到花園，挑一個你想練習的主題。','#home','回到我的花園')))();
 const official=document.querySelector('#official-audio');if(official)official.addEventListener('error',()=>{document.querySelector('#official-audio-status').textContent='錄音無法載入，請點下方「開啟官方錄音」或到官方備考頁播放。'});
 if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});
main.addEventListener('submit',e=>{
 if(e.target.id==='answer-form'){e.preventDefault();submitAnswer(e.target)}
 if(e.target.id==='vocab-search-form'){e.preventDefault();vocabQuery=new FormData(e.target).get('query')?.toString().trim()||'';cardIndex=0;wordPage=0;flipped=false;render(false);document.querySelector('#vocab-search')?.focus()}
});
main.addEventListener('input',e=>{if(e.target.id==='writing-draft'){const el=e.target,w=writing.find(w=>w.id===el.dataset.id);state.drafts[w.id]=el.value;document.querySelector('#word-count').textContent=`${wordCount(el.value)} / ${w.min} 字（至少）`;document.querySelector('#draft-status').textContent=persist()?'草稿已儲存在目前瀏覽器':'無法儲存，請自行複製保留草稿';}});
main.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn||btn.disabled)return;const a=btn.dataset.action,id=btn.dataset.id;
 if(a==='start-sprint'){const category=document.querySelector('#sprint-category').value,count=document.querySelector('#sprint-count').value;runSprint(category,count)}
 if(a==='continue-practice'){if(quiz.kind==='sprint'){runSprint(quiz.sprintCategory,quiz.sprintCount)}else if(quiz.kind==='review'){const remaining=state.mistakes.map(id=>questions.find(q=>q.id===id)).filter(Boolean);if(remaining.length)startQuiz(remaining,'錯題再練一次','review');else location.hash='sprint'}else{const categories=[...new Set(quiz.pool.map(q=>q.category))];runSprint(categories.length===1?categories[0]:'mixed',quiz.pool.length)}}
 if(a==='home-flip'){homeFlipped=!homeFlipped;render(false)}
 if(a==='say-example'){const v=vocabulary.find(v=>v.id===id);if(v?.example)speak(v.example)}
 if(a==='topic'){topic=btn.dataset.topic;cardIndex=0;wordPage=0;flipped=false;render(false)}
 if(a==='clear-vocab-search'){vocabQuery='';cardIndex=0;wordPage=0;flipped=false;render(false);document.querySelector('#vocab-search')?.focus()}
 if(a==='flip'){flipped=!flipped;render(false);document.querySelector('.flashcard')?.focus()}
 if(a==='prev-card'||a==='next-card'){stopSpeech();cardIndex+=a==='next-card'?1:-1;wordPage=Math.floor(cardIndex/WORDS_PER_PAGE);flipped=false;render(false);document.querySelector('.flashcard')?.focus()}
 if(a==='pick-card'){cardIndex=Number(btn.dataset.index);flipped=false;render(false);document.querySelector('.flashcard')?.focus()}
 if(a==='prev-word-page'||a==='next-word-page'){wordPage+=a==='next-word-page'?1:-1;cardIndex=wordPage*WORDS_PER_PAGE;flipped=false;render(false);document.querySelector('.flashcard')?.focus()}
 if(a==='vocab-quiz'){const pool=topic==='全部'?vocabQuestions:vocabQuestions.filter(q=>q.topic===topic);startQuiz(selectDaily(pool,`${todayKey()}-${state.answers.filter(a=>a.category==='vocabulary').length}`,6),`${topic==='全部'?'單字':topic}小測驗`)}
 if(a==='start-block'){const isReading=btn.dataset.category==='reading',size=isReading?6:5,pool=isReading?reading:listening,block=Number(btn.dataset.block);startQuiz(pool.slice(block*size,(block+1)*size),isReading?'閱讀小練習':'聽力小練習')}
 if(a==='next-question'&&quiz?.submitted){stopSpeech();quiz.index++;quiz.selected=null;quiz.submitted=false;render()}
 if(a==='play-question')speak(quiz.pool[quiz.index].script,Number(document.querySelector('#speech-rate').value));
 if(a==='stop-audio'){stopSpeech();const status=document.querySelector('#speech-status');if(status)status.textContent='已停止 · 按播放可以重新聽'}
 if(a==='review-all')startQuiz(state.mistakes.map(id=>questions.find(q=>q.id===id)).filter(Boolean),'錯題再練一次','review');
 if(a==='review-one')startQuiz(questions.filter(q=>q.id===id),'錯題再練一次','review');
 if(a==='finish-writing'){const w=writing.find(w=>w.id===id),feedback=document.querySelector('#writing-feedback'),count=wordCount(state.drafts[id]||'');if(count<w.min){feedback.textContent=`目前 ${count} 字，再試著多寫一點，達到至少 ${w.min} 字。`;return}if(document.querySelectorAll('[name="writing-check"]:checked').length!==4){feedback.textContent='先確認右側（手機下方）的四個檢查項目，再完成這次練習。';return}recordActivity(state,'writing',id);persist();feedback.textContent='這次寫作練習已記錄！可以請家人或老師再幫你讀一讀。';notify('寫作練習已記錄。每個任務每天記錄一次。')}
 if(a==='say-prompt'||a==='say-sample'){const s=speaking.find(s=>s.id===id);speak(a==='say-prompt'?s.question:s.sample)}
 if(a==='finish-speaking'){recordActivity(state,'speaking',id);persist();document.querySelector('#speaking-feedback').textContent='今天的口說練習已記錄。下次試試用不同的理由回答！';notify('口說練習已記錄。每個話題每天記錄一次。')}
});
